from functools import lru_cache
class T:
 @lru_cache
 def get_fixed_vocab(self): return ['a','b']
 @lru_cache
 def pieces(self, special=False):
  if special: return self.pieces().copy()
  self.id_to_piece=self.get_fixed_vocab()
  self.id_to_piece.append('<extra>')
  return self.id_to_piece
 @lru_cache
 def ords(self): self.id_to_ord=list(range(2))
